package demo;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/** Stub so the acceptance tests compile and boot. Endpoints arrive in T4. */
@SpringBootApplication
public class App {

    public static void main(String[] args) {
        SpringApplication.run(App.class, args);
    }
}

package demo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.fasterxml.jackson.databind.ObjectMapper;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.Map;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext;
import org.springframework.context.ConfigurableApplicationContext;

/** Acceptance tests for the v0 URL shortener, written before the implementation (TDD red). Black-box over HTTP. */
class AppTest {

    static ConfigurableApplicationContext ctx;
    static String base;
    static final HttpClient http = HttpClient.newBuilder().followRedirects(HttpClient.Redirect.NEVER).build();
    static final ObjectMapper json = new ObjectMapper();

    @BeforeAll
    static void start() {
        ctx = SpringApplication.run(App.class, "--server.port=0", "--app.base-url=http://short.test", "--logging.level.root=WARN");
        base = "http://localhost:" + ((ServletWebServerApplicationContext) ctx).getWebServer().getPort();
    }

    @AfterAll
    static void stop() {
        ctx.close();
    }

    static HttpResponse<String> post(String path, String body) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create(base + path)).header("Content-Type", "application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(), HttpResponse.BodyHandlers.ofString());
    }

    static HttpResponse<String> get(String path) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create(base + path)).GET().build(), HttpResponse.BodyHandlers.ofString());
    }

    @SuppressWarnings("unchecked")
    static Map<String, Object> body(HttpResponse<String> r) throws Exception {
        return json.readValue(r.body(), Map.class);
    }

    @Test
    void ac1_postCreatesASevenCharBase62ShortLink() throws Exception {
        HttpResponse<String> r = post("/api/links", "{\"url\":\"https://example.com/a\"}");
        assertEquals(201, r.statusCode(), r.body());
        String code = (String) body(r).get("code");
        assertTrue(code.matches("^[0-9A-Za-z]{7}$"), code);
        assertEquals("http://short.test/" + code, body(r).get("shortUrl"));
    }

    @Test
    void ac2_rejectsNonHttpAndMalformedUrlsWith400() throws Exception {
        for (String url : new String[] {"javascript:alert(1)", "ftp://x", "not a url", ""}) {
            assertEquals(400, post("/api/links", "{\"url\":\"" + url + "\"}").statusCode(), url);
        }
    }

    @Test
    void ac3_getCodeRedirectsWith302ToTheTarget() throws Exception {
        String code = (String) body(post("/api/links", "{\"url\":\"https://example.com/r\"}")).get("code");
        HttpResponse<String> r = get("/" + code);
        assertEquals(302, r.statusCode());
        assertEquals("https://example.com/r", r.headers().firstValue("Location").orElse(null));
    }

    @Test
    void ac4_unknownCodesReturn404() throws Exception {
        assertEquals(404, get("/zzzzzzz").statusCode());
    }

    @Test
    void ac5_statsCountClicksAndReportLastClickTime() throws Exception {
        String code = (String) body(post("/api/links", "{\"url\":\"https://example.com/s\"}")).get("code");
        get("/" + code);
        get("/" + code);
        HttpResponse<String> r = get("/api/links/" + code + "/stats");
        assertEquals(200, r.statusCode());
        assertEquals(2, body(r).get("clicks"));
        assertNotNull(body(r).get("lastClickAt"));
    }

    @Test
    void ac6_healthReportsOk() throws Exception {
        HttpResponse<String> r = get("/health");
        assertEquals(200, r.statusCode());
        assertEquals("ok", body(r).get("status"));
    }
}

package demo;

import java.security.SecureRandom;
import java.util.function.IntFunction;
import java.util.function.Predicate;

/**
 * Random base62 codes with rejection sampling (bytes >= 248 are discarded so every character is
 * equally likely). Random rather than sequential so codes cannot be enumerated.
 */
public final class Codes {

    public static final String BASE62 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private static final SecureRandom RANDOM = new SecureRandom();

    private Codes() {}

    public static String random(int length) {
        return random(length, n -> {
            byte[] b = new byte[n];
            RANDOM.nextBytes(b);
            return b;
        });
    }

    public static String random(int length, IntFunction<byte[]> bytes) {
        if (length < 1) throw new IllegalArgumentException("length must be >= 1");
        StringBuilder out = new StringBuilder(length);
        while (out.length() < length) {
            for (byte b : bytes.apply(length * 2)) {
                int v = b & 0xFF;
                if (v < 248) {
                    out.append(BASE62.charAt(v % 62));
                    if (out.length() == length) break;
                }
            }
        }
        return out.toString();
    }

    /** Generate a code that {@code exists} reports as free; bounded so a full keyspace can't spin forever. */
    public static String unique(Predicate<String> exists, int length, int maxAttempts) {
        for (int i = 0; i < maxAttempts; i++) {
            String c = random(length);
            if (!exists.test(c)) return c;
        }
        throw new IllegalStateException("no free code after " + maxAttempts + " attempts");
    }
}

package demo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;

class CodesTest {

    @Test
    void emitsBase62CodesOfTheRequestedLength() {
        for (int i = 0; i < 100; i++) {
            String c = Codes.random(7);
            assertEquals(7, c.length());
            for (char ch : c.toCharArray()) assertTrue(Codes.BASE62.indexOf(ch) >= 0);
        }
    }

    @Test
    void skipsBiasedBytes() {
        AtomicInteger calls = new AtomicInteger();
        String c = Codes.random(3, n -> {
            if (calls.incrementAndGet() == 1) return new byte[] {(byte) 255, (byte) 250, 0, 1, 2};
            byte[] b = new byte[n];
            java.util.Arrays.fill(b, (byte) 3);
            return b;
        });
        assertEquals("012", c);
    }

    @Test
    void retriesOnCollisionAndGivesUpAfterMaxAttempts() {
        AtomicInteger probes = new AtomicInteger();
        String code = Codes.unique(c -> probes.incrementAndGet() < 3, 7, 5);
        assertEquals(7, code.length());
        assertEquals(3, probes.get());
        assertThrows(IllegalStateException.class, () -> Codes.unique(c -> true, 7, 2));
    }
}

package demo;

import java.time.Instant;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Storage port + in-memory adapter. The interface is the seam for JDBC/Postgres later; v0 ships
 * in-memory so the service is runnable with zero setup.
 */
public interface LinkStore {

    record Link(String code, String targetUrl, Instant createdAt) {}

    record Stats(String code, long clicks, Instant lastClickAt) {}

    void insert(Link link);

    Optional<Link> find(String code);

    boolean exists(String code);

    void recordClick(String code, Instant at);

    Optional<Stats> stats(String code);

    final class InMemory implements LinkStore {
        private record Counter(long clicks, Instant last) {}

        private final Map<String, Link> links = new ConcurrentHashMap<>();
        private final Map<String, Counter> clicks = new ConcurrentHashMap<>();

        @Override
        public synchronized void insert(Link link) {
            if (links.containsKey(link.code())) throw new IllegalStateException("code '" + link.code() + "' already exists");
            links.put(link.code(), link);
            clicks.put(link.code(), new Counter(0, null));
        }

        @Override
        public Optional<Link> find(String code) {
            return Optional.ofNullable(links.get(code));
        }

        @Override
        public boolean exists(String code) {
            return links.containsKey(code);
        }

        @Override
        public void recordClick(String code, Instant at) {
            clicks.computeIfPresent(code, (k, c) -> new Counter(c.clicks() + 1, at));
        }

        @Override
        public Optional<Stats> stats(String code) {
            Counter c = clicks.get(code);
            return c == null ? Optional.empty() : Optional.of(new Stats(code, c.clicks(), c.last()));
        }
    }
}

package demo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.time.Instant;
import org.junit.jupiter.api.Test;

class LinkStoreTest {

    @Test
    void insertsFindsAndRejectsDuplicates() {
        LinkStore s = new LinkStore.InMemory();
        s.insert(new LinkStore.Link("abc1234", "https://example.com/", Instant.EPOCH));
        assertEquals("https://example.com/", s.find("abc1234").orElseThrow().targetUrl());
        assertTrue(s.exists("abc1234"));
        assertFalse(s.exists("nope"));
        assertTrue(s.find("nope").isEmpty());
        assertThrows(IllegalStateException.class, () -> s.insert(new LinkStore.Link("abc1234", "https://x.com/", Instant.EPOCH)));
    }

    @Test
    void countsClicksAndRemembersTheLastOne() {
        LinkStore s = new LinkStore.InMemory();
        s.insert(new LinkStore.Link("clk0001", "https://example.com/", Instant.EPOCH));
        assertEquals(0, s.stats("clk0001").orElseThrow().clicks());
        assertNull(s.stats("clk0001").orElseThrow().lastClickAt());
        Instant t1 = Instant.parse("2026-01-02T00:00:00Z");
        Instant t2 = Instant.parse("2026-01-03T00:00:00Z");
        s.recordClick("clk0001", t1);
        s.recordClick("clk0001", t2);
        assertEquals(new LinkStore.Stats("clk0001", 2, t2), s.stats("clk0001").orElseThrow());
        s.recordClick("missing", t2); // no-op
        assertTrue(s.stats("missing").isEmpty());
    }
}

package demo;

import java.net.URI;
import java.net.URISyntaxException;
import java.time.Instant;
import java.util.Locale;
import java.util.Map;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.CacheControl;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;

/** HTTP adapter: create, redirect (302 + no-store so every click is counted), stats, health. */
@RestController
public class LinkController {

    private final LinkStore store = new LinkStore.InMemory();
    private final String baseUrl;

    public LinkController(@Value("${app.base-url:http://localhost:8080}") String baseUrl) {
        this.baseUrl = baseUrl.endsWith("/") ? baseUrl.substring(0, baseUrl.length() - 1) : baseUrl;
    }

    /** Only absolute http(s) URLs may be shortened: anything else turns the redirect into an attack vector. */
    static String validateUrl(Object raw) {
        if (!(raw instanceof String s) || s.isBlank()) return null;
        try {
            URI u = new URI(s.trim());
            String scheme = u.getScheme() == null ? "" : u.getScheme().toLowerCase(Locale.ROOT);
            return (scheme.equals("http") || scheme.equals("https")) && u.getHost() != null ? u.toString() : null;
        } catch (URISyntaxException e) {
            return null;
        }
    }

    @GetMapping("/health")
    public Map<String, String> health() {
        return Map.of("status", "ok");
    }

    @PostMapping("/api/links")
    public ResponseEntity<Map<String, Object>> create(@RequestBody Map<String, Object> body) {
        String target = validateUrl(body.get("url"));
        if (target == null) return ResponseEntity.badRequest().body(Map.of("error", "INVALID_URL", "message", "only absolute http(s) URLs are accepted"));
        String code = Codes.unique(store::exists, 7, 5);
        LinkStore.Link link = new LinkStore.Link(code, target, Instant.now());
        store.insert(link);
        return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("code", code, "targetUrl", target, "createdAt", link.createdAt().toString(), "shortUrl", baseUrl + "/" + code));
    }

    @GetMapping("/api/links/{code:[0-9A-Za-z]{7}}/stats")
    public ResponseEntity<Map<String, Object>> stats(@PathVariable("code") String code) {
        return store.stats(code)
                .<ResponseEntity<Map<String, Object>>>map(s -> {
                    Map<String, Object> m = new java.util.LinkedHashMap<>();
                    m.put("code", s.code());
                    m.put("clicks", s.clicks());
                    m.put("lastClickAt", s.lastClickAt() == null ? null : s.lastClickAt().toString());
                    return ResponseEntity.ok(m);
                })
                .orElseGet(() -> ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("error", "NOT_FOUND")));
    }

    @GetMapping("/{code:[0-9A-Za-z]{7}}")
    public ResponseEntity<Void> redirect(@PathVariable("code") String code) {
        return store.find(code)
                .map(link -> {
                    store.recordClick(code, Instant.now());
                    return ResponseEntity.status(HttpStatus.FOUND).cacheControl(CacheControl.noStore()).location(URI.create(link.targetUrl())).<Void>build();
                })
                .orElseGet(() -> ResponseEntity.notFound().build());
    }
}
